<script setup>
import { ref, computed, onMounted, onUnmounted, nextTick, watch } from 'vue';
import { Sprout, LayoutDashboard, MessageSquare, GitCompareArrows, Library, FlaskConical, Network, ChevronDown, ChevronRight, Plus, ArrowUpRight, Search, Bell, CircleHelp, Upload, Download, FileText, Check, Clock3, X, Send, Sparkles, Database, Server, ShieldCheck, MoreHorizontal, CheckCheck, Menu, SlidersHorizontal, ExternalLink, Activity, RotateCcw, Cpu, Cable, CircleAlert, SquarePen } from 'lucide-vue-next';
import { initialTasks, initialDocs, quickQuestions } from './data';
import { api } from './api';

const nav = [{id:'overview',label:'工作台',icon:LayoutDashboard},{id:'chat',label:'农业问答',icon:MessageSquare},{id:'reviews',label:'双模型评审',icon:GitCompareArrows},{id:'knowledge',label:'知识资料',icon:Library},{id:'training',label:'模型训练',icon:FlaskConical},{id:'gateway',label:'模型中转',icon:Network}];
const route = ref(nav.some(n=>n.id===location.hash.slice(1))?location.hash.slice(1):'overview');
const mobileMenu=ref(false), toast=ref(''), dialog=ref(''), query=ref(''), filter=ref('全部'), period=ref('近 7 天');
const tasks=ref(structuredClone(initialTasks)), docs=ref(structuredClone(initialDocs));
for (const task of tasks.value) if(task.status==='待评审'&&Math.random()<0.5) task.answers.reverse();
const messages=ref([]), prompt=ref(''), busy=ref(false), chatEnd=ref(null), chatMode=ref('demo'), chatModel=ref('local_agri');
const pair=ref(null); // 当前盲评对: {question,aIdx,bIdx,aModel,bModel,similar,judge,judgeError}
const selections=ref([]); // 盲评偏好样本: {question,choice,chosen,rejected,chosen_model,rejected_model,similarity,judge_winner,ts}
const selected=ref(null), decision=ref(''), note=ref(''), finalAnswer=ref(''), reveal=ref(false), tab=ref('待评审');
const uploadFiles=ref([]), uploadDomain=ref('种植管理'), fileInput=ref(null), uploadError=ref('');
const provider=ref('兼容接口'), baseUrl=ref(''), modelName=ref(''), settingsSaved=ref(false), settingsError=ref('');
let timer, responseTimer;
const events=ref([{title:'创建农业 AI 工作空间',detail:'示例园区 · 内部试用',time:'初始示例'},{title:'已载入专家评审示例',detail:'可体验选择、修订与复审流程',time:'初始示例'},{title:'等待接入 DGX 与模型服务',detail:'模型与训练均未连接',time:'当前状态'}]);
const pending=computed(()=>tasks.value.filter(t=>t.status==='待评审'));
const checked=computed(()=>tasks.value.filter(t=>t.status==='已审核'));
const visibleTasks=computed(()=>tasks.value.filter(t=>(tab.value==='全部'||t.status===tab.value)&&(!query.value||t.title.includes(query.value))));
const visibleDocs=computed(()=>docs.value.filter(d=>(filter.value==='全部'||d.domain===filter.value)&&(!query.value||d.name.toLowerCase().includes(query.value.toLowerCase()))));
const title=computed(()=>nav.find(n=>n.id===route.value)?.label||'工作台');
function notify(text){toast.value=text;clearTimeout(timer);timer=setTimeout(()=>toast.value='',3500)}
function go(id){route.value=id;location.hash=id;mobileMenu.value=false;query.value='';filter.value='全部';selected.value=null}
function hashChange(){const id=location.hash.slice(1);if(nav.some(n=>n.id===id)){route.value=id;selected.value=null;query.value=''}}
function log(title,detail){events.value.unshift({title,detail,time:'刚刚'})}
function review(t){selected.value=t;decision.value=t.decision||'';note.value=t.note||'';finalAnswer.value=t.final||'';reveal.value=t.status==='待评审'?false:true}
function saveReview(){if(!decision.value){notify('请先选择评审结果');return}if(!finalAnswer.value.trim()){notify('请填写专家标准答案，或复制所选答案后修订');return}Object.assign(selected.value,{decision:decision.value,note:note.value.trim(),final:finalAnswer.value.trim(),status:'待复审'});reveal.value=true;log('提交一条专家评审',selected.value.title);selected.value=null;tab.value='待复审';notify('已提交待复审（本次演示会话）')}
function approve(){if(!finalAnswer.value.trim()){notify('标准答案不能为空');return}Object.assign(selected.value,{status:'已审核',final:finalAnswer.value.trim(),note:note.value.trim(),decision:decision.value});reveal.value=true;log('审核通过一条农业样本',selected.value.title);selected.value=null;tab.value='已审核';notify('已审核，可导出示例数据集')}
function exportData(){const rows=checked.value.map(t=>({id:t.id,messages:[{role:'user',content:t.question},{role:'assistant',content:t.final}],metadata:{demo:true,domain:t.domain,review_status:t.status}}));if(!rows.length){notify('暂无审核通过的样本');return}download(rows.map(x=>JSON.stringify(x)).join('\n'),'agri-demo-sft.jsonl','application/jsonl');notify(`已导出 ${rows.length} 条示例样本，非正式训练数据`)}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function ask(text){if(busy.value)return;const q=(text||prompt.value).trim();if(!q)return;prompt.value='';messages.value.push({role:'user',content:q});busy.value=true;await nextTick();chatEnd.value?.scrollIntoView({behavior:'smooth'});
 if(chatMode.value==='backend'){const history=messages.value.map(({role,content})=>({role,content}));const got=[];let pending=2;const settle=()=>{if(--pending===0){if(got.length===2)setupPair(q,got[0],got[1]);else if(got.length===1){messages.value[got[0].idx].sourceHidden=false;notify('仅一路模型可用，已直接显示来源')}busy.value=false}};api.chat({model:'local_agri',messages:history}).then(r=>{if(typeof r.answer==='string'){const idx=messages.value.push({role:'assistant',content:r.answer,model:'本地AI · qwen2.5:7b',demo:false,sourceHidden:true})-1;got.push({idx,model:'本地AI · qwen2.5:7b',content:r.answer});nextTick(()=>chatEnd.value?.scrollIntoView({behavior:'smooth'}))}}).catch(()=>{messages.value.push({role:'error',content:'本地模型未响应，请检查 Ollama 是否运行。'})}).finally(()=>settle());api.chat({model:'local2_agri',messages:history}).then(r=>{if(typeof r.answer==='string'){const m='云端AI · '+(r.model||'local2_agri');const idx=messages.value.push({role:'assistant',content:r.answer,model:m,demo:false,sourceHidden:true})-1;got.push({idx,model:m,content:r.answer});nextTick(()=>chatEnd.value?.scrollIntoView({behavior:'smooth'}))}}).catch(()=>{messages.value.push({role:'error',content:'另一路模型未响应，请稍后重试（云端限流或本地服务未运行）。'})}).finally(()=>settle());}
 else{await new Promise(resolve=>{responseTimer=setTimeout(resolve,450)});messages.value.push({role:'assistant',demo:true,content:'这是一条预置演示回答，尚未调用真实模型。\n\n分析这类种植问题，建议先整理以下信息：\n1. 作物、品种、生育期与土培 / 基质栽培方式。\n2. 最近的环境与根区检测记录，包含时间和单位。\n3. 灌溉、施肥、巡检及设备实际运行情况。\n\n信息补充完整后，应结合经过审核的农艺资料形成建议。当前尚未接入园区实时数据，无法判断现场情况。'});busy.value=false}
 await nextTick();chatEnd.value?.scrollIntoView({behavior:'smooth'});
}
function newChat(){if(busy.value){notify('请等待当前请求结束');return}messages.value=[];prompt.value='';go('chat')}
function toggleMode(){chatMode.value=chatMode.value==='demo'?'backend':'demo';go('chat');notify(chatMode.value==='backend'?'已切换到后端模式：发送消息将请求真实模型服务':'已切换回演示模式：使用预置回答')}
function addToReview(m){const i=messages.value.indexOf(m),q=messages.value[i-1]?.content||'农业问题';tasks.value.unshift({id:`RV-${Date.now()}`,title:q,question:q,domain:'种植管理',crop:'待标注',date:'刚刚',status:'待评审',answers:[{text:m.content,model:m.model||'未标注来源'}]});notify('已加入评审队列，模型来源已标注');log('新增评审任务',q)}
function setupPair(question,a,b){const swap=Math.random()<0.5;const A=swap?b:a,B=swap?a:b;pair.value={question,aIdx:A.idx,bIdx:B.idx,aModel:A.model,bModel:B.model,similar:null,judge:null,judgeError:false};api.similarity(A.content,B.content).then(r=>{if(pair.value&&pair.value.question===question)pair.value.similar=r.verdict}).catch(()=>{});api.judge(question,A.content,B.content).then(r=>{if(pair.value&&pair.value.question===question)pair.value.judge=r}).catch(()=>{if(pair.value&&pair.value.question===question)pair.value.judgeError=true})}
function addPairToReview(p){const A=messages.value[p.aIdx],B=messages.value[p.bIdx];tasks.value.unshift({id:`RV-${Date.now()}`,title:p.question.slice(0,36),question:p.question,domain:'种植管理',crop:'待标注',date:'刚刚',status:'待评审',auto:true,answers:[{text:A.content,model:p.aModel},{text:B.content,model:p.bModel}]});log('新增评审任务(差异大自动入队)',p.question.slice(0,20))}
function chooseBlind(choice){if(!pair.value)return;const p=pair.value;const A=messages.value[p.aIdx],B=messages.value[p.bIdx];A.sourceHidden=false;B.sourceHidden=false;const rec={question:p.question,choice,chosen:choice==='A'?A.content:choice==='B'?B.content:'',rejected:choice==='A'?B.content:choice==='B'?A.content:'',chosen_model:choice==='A'?p.aModel:choice==='B'?p.bModel:'',rejected_model:choice==='A'?p.bModel:choice==='B'?p.aModel:'',similarity:p.similar,judge_winner:p.judge?.winner||null,judge_a:p.judge?.score_a||null,judge_b:p.judge?.score_b||null,ts:Date.now()};if(choice==='A'||choice==='B')selections.value.unshift(rec);const judgeTxt=p.judge?` · AI裁判：${p.judge.winner==='A'?'A更好':p.judge.winner==='B'?'B更好':'两者相当'}（${p.judge.score_a} vs ${p.judge.score_b}）`:p.judgeError?' · AI裁判暂不可用（限流）':'';if(p.similar==='different'){addPairToReview(p);notify(`已${choice==='tie'?'记录：两者相当':'记录偏好样本'}，来源已揭示${judgeTxt}；两回答差异较大，已自动加入评审队列`)}else notify(`已${choice==='tie'?'记录：两者相当':'记录偏好样本'}，来源已揭示${judgeTxt}`);pair.value=null}
function exportDpo(){const rows=selections.value.filter(s=>s.chosen&&s.rejected).map(s=>({instruction:s.question,chosen:s.chosen,rejected:s.rejected,meta:{chosen_model:s.chosen_model,rejected_model:s.rejected_model,similarity:s.similarity,judge_winner:s.judge_winner}}));if(!rows.length){notify('暂无盲评偏好样本，先在农业问答中做一次选择');return}download(rows.map(x=>JSON.stringify(x)).join('\n'),'agri-dpo-pairs.jsonl','application/jsonl');notify(`已导出 ${rows.length} 条 DPO 偏好对（chosen/rejected）`)}
function handleFiles(e){uploadFiles.value=[...(e.target.files||[])];uploadError.value=''}
function registerFiles(){if(!uploadFiles.value.length){uploadError.value='请先选择文件';return}if(uploadFiles.value.some(f=>f.size>20*1024*1024)){uploadError.value='单个文件不能超过 20 MB';return}if(uploadFiles.value.some(f=>!/\.(pdf|docx|txt)$/i.test(f.name))){uploadError.value='仅支持 PDF、DOCX、TXT 文件';return}for(const f of uploadFiles.value)docs.value.unshift({id:`DOC-${Date.now()}-${f.name}`,name:f.name,type:f.name.split('.').pop().toUpperCase(),domain:uploadDomain.value,size:f.size>1024*1024?`${(f.size/1024/1024).toFixed(1)} MB`:`${Math.ceil(f.size/1024)} KB`,status:'待接入上传服务',date:new Date().toISOString().slice(0,10),source:'本次会话 · 仅文件信息'});log('登记资料信息',`${uploadFiles.value.length} 个文件，原文件未上传`);dialog.value='';uploadFiles.value=[];notify('已登记文件信息；原文件未上传，未解析入库')}
function saveConfig(){try{const u=new URL(baseUrl.value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)throw Error();if(!modelName.value.trim())throw Error();settingsError.value='';settingsSaved.value=true;notify('配置草稿已保留在本次会话，尚未连接供应商')}catch{settingsError.value='请填写有效的 HTTP(S) 地址和模型名称，地址不要包含凭证、查询参数或锚点。'}}
function exportConfig(){if(!settingsSaved.value){notify('请先校验并保存配置草稿');return}download(JSON.stringify({demo_config:true,models:{cloud_primary:{adapter:provider.value==='兼容接口'?'openai_compatible':'vendor_native',base_url:baseUrl.value,model:modelName.value,credential_ref:'CLOUD_PRIMARY_API_KEY'}}},null,2),'model-gateway.example.json')}
function openDialog(name){dialog.value=name;uploadError.value=''}
let previousFocus;
watch(dialog,async(value,old)=>{if(value&&!old){previousFocus=document.activeElement;await nextTick();document.querySelector('.modal button')?.focus()}else if(!value){previousFocus?.focus()}});
function escape(e){if(e.key==='Escape'){dialog.value='';mobileMenu.value=false}if(e.key==='Tab'&&dialog.value){const items=[...document.querySelectorAll('.modal button:not([disabled]), .modal input:not([hidden]), .modal select, .modal textarea')].filter(el=>el.offsetParent!==null);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
onMounted(()=>{window.addEventListener('hashchange',hashChange);window.addEventListener('keydown',escape);const ctx=document.modelContext;if(ctx?.registerTool)Promise.resolve(ctx.registerTool({name:'navigate_agri_workspace',description:'打开农业工作台中的一个页面，不提交数据。',inputSchema:{type:'object',properties:{page:{type:'string',enum:nav.map(n=>n.id)}},required:['page'],additionalProperties:false},execute(input){if(!nav.some(n=>n.id===input.page))throw new Error('未知页面');go(input.page);return {page:route.value}},annotations:{readOnlyHint:true}})).catch(()=>{})});
onUnmounted(()=>{window.removeEventListener('hashchange',hashChange);window.removeEventListener('keydown',escape);clearTimeout(timer);clearTimeout(responseTimer)});
</script>

<template>
<div class="app-shell">
 <div v-if="mobileMenu" class="sidebar-shade" @click="mobileMenu=false"></div>
 <aside class="sidebar" :class="{open:mobileMenu}">
  <a href="#overview" class="brand" @click.prevent="go('overview')"><span class="brand-mark"><Sprout :size="25"/></span><span>青禾 <small>AGRI INTELLIGENCE</small></span></a>
  <button class="workspace-switch" @click="openDialog('workspace')"><span class="workspace-symbol">禾</span><span>农业 AI 工作空间<small>208 亩示范园区</small></span><ChevronDown :size="15"/></button>
  <div class="nav-caption">工作空间</div>
  <nav aria-label="主导航"><button v-for="item in nav" :key="item.id" :class="['nav-item',{active:route===item.id}]" @click="go(item.id)"><component :is="item.icon" :size="19"/><span>{{item.label}}</span><span v-if="item.id==='reviews'&&pending.length" class="nav-count">{{pending.length}}</span></button></nav>
  <div class="sidebar-bottom"><div class="phase-card"><div><span class="tiny-square"></span> 第一阶段 · AI 数据闭环</div><p>从专业经验，到农业智能。</p><div class="phase-line"><i></i></div><span>当前版本：Web 交互原型</span></div><button class="help-link" @click="openDialog('help')"><CircleHelp :size="18"/>使用说明<span>↗</span></button><div class="profile"><span class="avatar">农</span><div>园区管理员<small>演示身份 · 尚未登录</small></div><button aria-label="查看账户说明" @click="openDialog('workspace')"><MoreHorizontal :size="19"/></button></div></div>
 </aside>
 <div class="main-shell">
  <header class="topbar"><div class="breadcrumb"><button class="mobile-trigger" aria-label="打开菜单" @click="mobileMenu=true"><Menu :size="22"/></button><span>农业 AI 平台</span><ChevronRight :size="14"/><strong>{{title}}</strong></div><div class="top-actions"><button class="demo-pill" @click="toggleMode" :aria-label="chatMode==='demo'?'切换为后端模式':'切换为演示模式'">{{chatMode==='demo'?'演示模式':'后端模式'}}</button><span class="top-divider"></span><button aria-label="查看通知" @click="openDialog('notifications')"><Bell :size="19"/><span class="notification-dot"></span></button><button class="top-avatar" aria-label="账户信息" @click="openDialog('workspace')">农</button></div></header>
  <main>
   <template v-if="route==='overview'">
    <section class="page-heading"><div><div class="eyebrow">WORKSPACE OVERVIEW</div><h1>让每一份农业经验，成为智能的养分。</h1><p>从问答到评审，从知识到训练，在这里建立你的农业 AI 数据闭环。</p></div><button class="primary" @click="newChat"><Plus :size="18"/>发起农业问答</button></section>
    <div class="notice"><span><CircleAlert :size="16"/>当前为交互演示，以下为示例数据；修改仅保留在本次页面会话，刷新后重置。</span><button @click="openDialog('help')">了解当前版本 <ChevronRight :size="14"/></button></div>
    <section class="stats-grid">
     <article class="stat"><div><span>农业问答</span><MessageSquare :size="19"/></div><strong>{{messages.filter(m=>m.role==='user').length}}<small>次</small></strong><p>本次会话产生的提问<span class="subtle-tag">当前</span></p></article>
     <article class="stat"><div><span>待专家评审</span><GitCompareArrows :size="19"/></div><strong>{{pending.length}}<small>条</small></strong><p>等待专业判断与修订<button @click="go('reviews')">去处理 <ArrowUpRight :size="14"/></button></p></article>
     <article class="stat"><div><span>知识资料</span><Library :size="19"/></div><strong>{{docs.length}}<small>份</small></strong><p>示例与本次登记的资料<span class="subtle-tag">含示例</span></p></article>
     <article class="stat"><div><span>已审核样本</span><Database :size="19"/></div><strong>{{checked.length}}<small>条</small></strong><p>可导出体验数据集<span class="subtle-tag">含示例</span></p></article>
    </section>
    <div class="overview-grid">
     <section class="panel review-panel"><div class="panel-heading"><div><h2>待办评审 <span class="count-label">{{pending.length}}</span></h2><p>专业判断，是模型成长的第一步。</p></div><button class="text-button" @click="go('reviews')">全部任务 <ChevronRight :size="15"/></button></div><div class="task-list"><div v-for="t in pending.slice(0,3)" :key="t.id" class="task-row"><span class="task-icon"><GitCompareArrows :size="19"/></span><div class="task-copy"><h3>{{t.title}}</h3><p><span>{{t.domain}}</span><span>{{t.crop}}</span><span>{{t.id}}</span></p></div><button class="outline small" @click="go('reviews');review(t)">开始评审</button></div><div v-if="!pending.length" class="empty-inline"><CheckCheck :size="26"/>本次会话的待评审任务已处理完成</div></div><div class="review-footer"><ShieldCheck :size="16"/>回答随机排列，评审提交前默认隐藏模型来源。</div></section>
     <section class="grow-card"><div class="grow-top"><span>AGRI LEARNING LOOP</span><Sprout :size="25"/></div><h2>把经验留下来，<br>让模型更懂农业。</h2><p>用经过专家审核的真实案例，<br>积累属于园区的专业知识。</p><div class="loop-steps"><span>提问</span><i></i><span>评审</span><i></i><span>样本</span><i></i><span>训练</span></div><button @click="go('reviews')">进入专家工作台 <ArrowUpRight :size="17"/></button></section>
     <section class="panel trend-panel"><div class="panel-heading"><div><h2>数据积累趋势</h2><p>标注与审核情况 · 演示图表</p></div><select v-model="period" aria-label="趋势时间范围"><option>近 7 天</option><option>近 30 天</option></select></div><div class="chart-legend"><span><i class="green-dot"></i>已标注</span><span><i class="gray-dot"></i>已审核</span><span class="sample-label">示意数据</span></div><div class="chart" role="img" :aria-label="`${period}示意趋势图，非真实统计`"><div class="y-axis"><span>40</span><span>30</span><span>20</span><span>10</span><span>0</span></div><div class="plot"><div class="grid-lines"><i></i><i></i><i></i><i></i><i></i></div><svg viewBox="0 0 600 150" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#20875c" stop-opacity=".17"/><stop offset="100%" stop-color="#20875c" stop-opacity="0"/></linearGradient></defs><path :d="period==='近 7 天'?'M0 126 C45 127 65 105 100 108 S160 84 200 90 S265 112 300 73 S365 80 400 49 S465 63 500 31 S560 32 600 10 L600 150 L0 150Z':'M0 140 C90 138 80 90 150 105 S220 62 300 74 S390 35 450 44 S530 30 600 5 L600 150 L0 150Z'" fill="url(#area)"/><path d="M0 140 C45 135 65 127 100 130 S165 107 200 114 S260 109 300 102 S365 84 400 90 S465 70 500 77 S560 50 600 55" fill="none" stroke="#a5bdb4" stroke-width="2.5" stroke-dasharray="5 5"/><path :d="period==='近 7 天'?'M0 126 C45 127 65 105 100 108 S160 84 200 90 S265 112 300 73 S365 80 400 49 S465 63 500 31 S560 32 600 10':'M0 140 C90 138 80 90 150 105 S220 62 300 74 S390 35 450 44 S530 30 600 5'" fill="none" stroke="#21865d" stroke-width="3"/></svg><div class="x-axis"><span v-for="d in (period==='近 7 天'?['10/03','10/04','10/05','10/06','10/07','10/08','10/09']:['09/10','09/15','09/20','09/25','09/30','10/05','10/09'])">{{d}}</span></div></div></div></section>
     <section class="panel runtime-panel"><div class="panel-heading"><h2>模型服务</h2><button class="text-button" @click="go('gateway')">管理 <ChevronRight :size="15"/></button></div><div class="model-row"><span class="model-icon"><Cpu :size="22"/></span><div><strong>本地农业模型</strong><small>Qwen3.8-27B · DGX Spark</small></div><span class="badge neutral">待接入</span></div><div class="model-row"><span class="model-icon cloud"><Network :size="22"/></span><div><strong>云端模型</strong><small>通过统一接口灵活替换</small></div><span class="badge neutral">未连接</span></div><div class="runtime-note"><Server :size="17"/><div><strong>本地优先，按需调用云端</strong><p>模型密钥由后端管理，前端不保存。</p></div></div></section>
    </div>
    <section class="panel activity-panel"><div class="panel-heading"><h2>最近动态</h2><span class="muted">本次演示会话</span></div><div class="activities"><div v-for="(e,i) in events.slice(0,3)" :key="i"><span class="activity-icon"><Check :size="15"/></span><div><strong>{{e.title}}</strong><p>{{e.detail}}</p></div><small>{{e.time}}</small></div></div></section>
   </template>

   <template v-else-if="route==='chat'">
    <section class="page-heading"><div><div class="eyebrow">AGRICULTURE ASSISTANT</div><h1>农业问答</h1><p>围绕种植、农业设备与服务，积累有依据的专业回答。</p></div><button class="outline" @click="newChat"><Plus :size="17"/>新建会话</button></section>
    <div class="chat-layout"><section class="panel chat-panel"><div class="chat-toolbar"><span><Sprout :size="19"/><strong>农业助手</strong></span><select v-model="chatMode" aria-label="问答模式" :disabled="busy"><option value="demo">演示模式 · 预置回答</option><option value="backend">后端模式 · 需要部署 API</option></select></div><div class="chat-messages"><div v-if="!messages.length" class="chat-welcome"><span class="welcome-icon"><Sprout :size="35"/></span><h2>从一个农业问题开始</h2><p>把种植经验、现场问题和专业判断连接起来。</p><div class="suggestions"><button v-for="q in quickQuestions" @click="ask(q)">{{q}}<ArrowUpRight :size="17"/></button></div></div><div v-for="(m,i) in messages" :key="i" :class="['message',m.role]"><span class="message-avatar"><Sprout v-if="m.role!=='user'" :size="19"/><span v-else>我</span></span><div class="message-body"><div class="message-name">{{m.role==='user'?'我的提问':m.role==='error'?'服务提示':'农业助手'}}<span v-if="m.model&&!m.sourceHidden" :class="['badge',m.model.includes('本地')?'local':'cloud']">{{m.model}}</span><span v-else-if="m.model&&m.sourceHidden" class="badge neutral">盲评中 · 来源隐藏</span><span v-else-if="m.demo" class="badge neutral">演示回答</span></div><div class="message-content">{{m.content}}</div><button v-if="m.role==='assistant'" class="text-button" @click="addToReview(m)"><GitCompareArrows :size="15"/>加入评审队列</button></div></div><div v-if="busy" class="loading-message"><span class="spinner"></span>{{chatMode==='demo'?'正在展示演示回答…':'正在请求后端服务…'}}</div><div v-if="pair&&!busy" class="blind-picker"><div class="blind-title"><ShieldCheck :size="15"/>哪个回答更优秀？（盲评 · 来源已隐藏）<span v-if="pair.similar==='different'" class="badge amber">差异较大</span><span v-else-if="pair.similar==='similar'" class="badge neutral">内容相近</span><span v-if="pair.judge" class="badge cloud">AI裁判：{{pair.judge.winner==='A'?'A更好':pair.judge.winner==='B'?'B更好':'两者相当'}} {{pair.judge.score_a}}/{{pair.judge.score_b}}</span><span v-else-if="pair.judgeError" class="badge neutral">AI裁判限流中</span></div><div class="blind-buttons"><button class="choice" @click="chooseBlind('A')">A 更优秀</button><button class="choice" @click="chooseBlind('B')">B 更优秀</button><button class="choice flat" @click="chooseBlind('tie')">都差不多</button></div></div><div ref="chatEnd"></div></div><form class="composer" @submit.prevent="ask()"><textarea v-model="prompt" aria-label="输入农业问题" placeholder="描述你的农业问题，补充作物、生育期和现场条件…" rows="3" maxlength="4000" @keydown.ctrl.enter.prevent="ask()"></textarea><div><span>{{chatMode==='demo'?'演示不调用模型，不读取园区实时数据':'请求发送至同源业务后端'}} · Ctrl + Enter 发送</span><button class="primary" :disabled="busy||!prompt.trim()" type="submit"><Send :size="16"/>发送</button></div></form></section><aside class="chat-context"><section class="panel"><h3>让回答更有依据</h3><p>提问时尽量补充：</p><ul><li>作物、品种与生育期</li><li>地区、设施与种植方式</li><li>测量时间、数值与单位</li><li>近期农事与设备状态</li></ul></section><section class="panel"><div class="section-icon"><Library :size="20"/></div><h3>企业农业知识</h3><p>真实资料检索尚未接入。当前回答不会引用示例文件。</p><button class="text-button" @click="go('knowledge')">管理资料 <ChevronRight :size="15"/></button></section></aside></div>
   </template>

   <template v-else-if="route==='reviews'">
    <section class="page-heading"><div><div class="eyebrow">EXPERT REVIEW</div><h1>双模型评审</h1><p>用专业判断选出好回答，再把它打磨成可信的农业样本。</p></div><div class="heading-actions"><button class="outline" @click="exportDpo"><Download :size="17"/>导出 DPO 偏好集</button><button class="outline" @click="exportData"><Download :size="17"/>导出已审核样本</button></div></section>
    <template v-if="!selected"><div class="notice"><span><ShieldCheck :size="16"/>当前为示例评审任务。结果仅在本次会话保留，可导出体验流程。</span></div><section class="panel"><div class="table-toolbar"><div class="tabs"><button v-for="s in ['待评审','待复审','已审核','全部']" :class="{active:tab===s}" @click="tab=s">{{s}}<span>{{s==='全部'?tasks.length:tasks.filter(t=>t.status===s).length}}</span></button></div><label class="search"><Search :size="16"/><input v-model="query" placeholder="搜索评审问题" aria-label="搜索评审问题"/></label></div><div class="table-scroll"><table><thead><tr><th>问题 / 任务编号</th><th>领域</th><th>作物</th><th>状态</th><th>时间</th><th>操作</th></tr></thead><tbody><tr v-for="t in visibleTasks" :key="t.id"><td><strong>{{t.title}}</strong><small>{{t.id}}</small></td><td>{{t.domain}}</td><td>{{t.crop}}</td><td><span :class="['badge',t.status==='已审核'?'success':t.status==='待复审'?'amber':'neutral']">{{t.status}}</span></td><td>{{t.date}}</td><td><button class="text-button" @click="review(t)">{{t.status==='待评审'?'开始评审':t.status==='待复审'?'复审':'查看'}}<ChevronRight :size="15"/></button></td></tr><tr v-if="!visibleTasks.length"><td colspan="6" class="empty-cell">没有符合条件的任务</td></tr></tbody></table></div></section></template>
    <template v-else><button class="text-button back" @click="selected=null">返回任务列表</button><section class="panel question-panel"><div><span class="badge neutral">{{selected.domain}}</span><span class="muted">{{selected.id}} · 示例任务</span></div><h2>{{selected.question}}</h2><p>请独立评价准确性、适用条件和可执行性；表达流畅不等于事实正确。</p></section><div v-if="selected.answers.length" class="answer-grid"><article v-for="(a,i) in selected.answers" :key="i" class="panel answer-card"><div class="panel-heading"><h3><span class="answer-letter">{{String.fromCharCode(65+i)}}</span>候选回答</h3><span v-if="reveal" :class="['badge',a.model&&a.model.includes('本地')?'local':(a.model&&a.model.includes('云端')?'cloud':'neutral')]">{{a.model||'未标注来源'}}</span><span v-else class="muted">盲评中 · 来源隐藏</span></div><div class="answer-text">{{a.text}}</div><button class="text-button" :disabled="selected.status==='已审核'" @click="finalAnswer=a.text;notify('已复制至专家标准答案，可继续修订')"><SquarePen :size="15"/>以此为基础修订</button></article></div><section class="panel review-form"><h2>专家判断</h2><div class="choice-row"><button v-for="d in ['A 更好','B 更好','两者都合格','两者都不合格','无法判断']" :class="['choice',{selected:decision===d}]" :disabled="selected.status==='已审核'||((d==='B 更好'||d.startsWith('两者'))&&selected.answers.length<2)" @click="decision=d">{{d}}<Check v-if="decision===d" :size="15"/></button></div><label>优化建议<textarea v-model="note" :readonly="selected.status==='已审核'" rows="2" placeholder="具体指出事实错误、缺失条件或可改进的表达…"></textarea></label><label>专家标准答案 <span class="required">*</span><textarea v-model="finalAnswer" :readonly="selected.status==='已审核'" rows="5" placeholder="基于已核实的事实修订答案；没有足够信息时，写出需要追问的内容。"></textarea></label><div class="form-footer"><button class="text-button" @click="reveal=!reveal">{{reveal?'隐藏模型来源':'查看模型来源'}}</button><div><button class="outline" @click="selected=null">返回</button><button v-if="selected.status==='待复审'" class="primary" @click="approve"><CheckCheck :size="17"/>审核通过</button><button v-else-if="selected.status!=='已审核'" class="primary" @click="saveReview">提交复审</button><span v-else class="badge success">已审核 · 只读</span></div></div></section></template>
   </template>

   <template v-else-if="route==='knowledge'">
    <section class="page-heading"><div><div class="eyebrow">KNOWLEDGE LIBRARY</div><h1>知识资料</h1><p>有来源、可追溯的资料，是农业智能的基础。</p></div><button class="primary" @click="openDialog('upload')"><Upload :size="17"/>登记资料</button></section><div class="notice"><span><CircleAlert :size="16"/>演示版仅登记文件信息，不上传原文件，不执行解析、向量化或知识检索。</span></div><div class="knowledge-categories"><button v-for="(d,i) in ['全部','种植管理','农业物联网','农业销售']" :class="['category',{selected:filter===d}]" @click="filter=d"><component :is="[Library,Sprout,Cable,FileText][i]" :size="23"/><div><strong>{{d==='全部'?'全部资料':d}}</strong><span>{{d==='全部'?docs.length:docs.filter(x=>x.domain===d).length}} 份资料</span></div></button></div><section class="panel"><div class="panel-heading"><h2>资料列表</h2><label class="search"><Search :size="16"/><input v-model="query" placeholder="搜索资料名称" aria-label="搜索资料名称"/></label></div><div class="table-scroll"><table><thead><tr><th>资料名称</th><th>领域</th><th>状态</th><th>登记时间</th><th>操作</th></tr></thead><tbody><tr v-for="d in visibleDocs" :key="d.id"><td><div class="file-cell"><span :class="['file-icon',d.type.toLowerCase()]"><FileText :size="23"/></span><div><strong>{{d.name}}</strong><small>{{d.type}} · {{d.size}} · {{d.source}}</small></div></div></td><td>{{d.domain}}</td><td><span class="badge neutral">{{d.status}}</span></td><td>{{d.date}}</td><td><button class="text-button" @click="notify(d.status==='示例资料'?'这是示例目录，未附带真实文件':'文件只登记在本次会话，尚未上传到服务器')">查看信息<ChevronRight :size="15"/></button></td></tr><tr v-if="!visibleDocs.length"><td colspan="5" class="empty-cell">没有符合条件的资料</td></tr></tbody></table></div></section><div class="pipeline panel"><h3>知识入库流程</h3><div><span>原始资料</span><ChevronRight/><span>解析与清洗</span><ChevronRight/><span>专家审核</span><ChevronRight/><span>发布知识库</span></div><p>正式后端接入后，每个环节将保留来源、版本和审核记录。</p></div>
   </template>

   <template v-else-if="route==='training'">
    <section class="page-heading"><div><div class="eyebrow">MODEL DEVELOPMENT</div><h1>模型训练</h1><p>先形成高质量样本，再用评测验证每一次改进。</p></div><button class="outline" @click="exportData"><Download :size="17"/>导出示例数据集</button></section><div class="training-banner"><span class="training-mark"><Cpu :size="34"/></span><div><span class="badge light">等待设备接入</span><h2>你的农业模型，从这里开始成长。</h2><p>DGX Spark · 128GB 统一内存 · 4TB 存储（规划配置）</p></div><button class="light-button" @click="openDialog('training')">查看接入清单 <ChevronRight :size="16"/></button></div><div class="training-grid"><section class="panel"><div class="panel-heading"><h2>训练准备</h2><span class="badge amber">准备中</span></div><div class="checklist"><div><span class="check-circle done"><Check :size="15"/></span><div><strong>专家标注流程</strong><p>前端可体验选择、修订与复审</p></div></div><div><span class="check-circle">2</span><div><strong>积累真实农业样本</strong><p>当前 {{checked.length}} 条审核示例，不能作为正式数据</p></div></div><div><span class="check-circle">3</span><div><strong>确认同源训练权重</strong><p>部署量化包不等同于已验证训练底座</p></div></div><div><span class="check-circle">4</span><div><strong>连接 DGX 与评测服务</strong><p>尚未发起任何实际训练</p></div></div></div></section><section class="panel"><div class="panel-heading"><h2>模型版本</h2><span class="muted">尚无发布版本</span></div><div class="model-empty"><FlaskConical :size="38"/><h3>等待第一轮训练</h3><p>完成数据审核、训练与独立评测后，<br>候选版本将出现在这里。</p><button class="outline" @click="go('reviews')">前往专家评审</button></div></section></div><section class="panel pipeline"><h3>每次进步，都有迹可循</h3><div><span>数据集版本</span><ChevronRight/><span>LoRA 微调</span><ChevronRight/><span>独立评测</span><ChevronRight/><span>审核发布</span></div><p>保留模型、数据、提示词、技能和策略版本，支持回退到稳定版本。</p></section>
   </template>

   <template v-else-if="route==='gateway'">
    <section class="page-heading"><div><div class="eyebrow">MODEL GATEWAY</div><h1>模型中转</h1><p>本地模型与云端服务使用统一入口，业务流程不绑定供应商。</p></div><button class="outline" @click="exportConfig"><Download :size="17"/>导出配置草稿</button></section><div class="notice"><span><ShieldCheck :size="16"/>此页面只编辑配置草稿，不直接连接供应商。API 密钥应在后端环境变量中配置。</span></div><div class="gateway-grid"><section class="panel"><div class="panel-heading"><h2><Cpu :size="20"/> 本地农业模型</h2><span class="badge neutral">待接入</span></div><div class="model-detail"><span class="model-monogram">Q</span><h3>Qwen3.8-27B-Uncensored</h3><p>orcarouter · 本地部署候选</p></div><dl class="spec-list"><div><dt>逻辑名称</dt><dd>local_agri</dd></div><div><dt>计算设备</dt><dd>DGX Spark</dd></div><div><dt>系统环境</dt><dd>DGX OS / Ubuntu · ARM64</dd></div><div><dt>推理服务</dt><dd>待验证 Ollama / vLLM</dd></div><div><dt>当前连接</dt><dd>未连接</dd></div></dl><button class="outline full" @click="openDialog('training')">查看本地接入说明</button></section><section class="panel gateway-form"><div class="panel-heading"><h2><Network :size="20"/> 云端模型</h2><span class="badge neutral">{{settingsSaved?'草稿已保存':'未配置'}}</span></div><form @submit.prevent="saveConfig"><label>协议适配器<select v-model="provider" @change="settingsSaved=false"><option>兼容接口</option><option>供应商原生接口</option></select></label><label>API 基础地址<input v-model="baseUrl" @input="settingsSaved=false" placeholder="https://your-provider.example/v1" type="url" required/></label><label>模型名称<input v-model="modelName" @input="settingsSaved=false" placeholder="填写供应商提供的模型名称" required maxlength="150"/></label><label>密钥环境变量<input value="CLOUD_PRIMARY_API_KEY" readonly/><small>不在浏览器输入或保存真实密钥。</small></label><p v-if="settingsError" class="error-text" role="alert">{{settingsError}}</p><button class="primary full" type="submit">校验并保存草稿</button></form></section></div><section class="panel pipeline"><h3>统一调用路径</h3><div><span>农业工作台 / Hermes</span><ChevronRight/><span>策略与权限</span><ChevronRight/><span>模型网关</span><ChevronRight/><span>本地 / 云端</span></div><p>供应商故障需明确记录；双模型评审不静默替换模型来源。</p></section>
   </template>
   <footer class="page-footer"><span><Sprout :size="14"/> 青禾 · 农业 AI 工作台</span><span>本地部署优先 <i>·</i> Web 原型 v0.1</span></footer>
  </main>
 </div>
 <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Check :size="18"/>{{toast}}</div></Transition>
 <div v-if="dialog" class="modal-backdrop" @click.self="dialog=''"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-heading"><h2 id="modal-title">{{({upload:'登记农业资料',help:'当前版本说明',workspace:'农业 AI 工作空间',notifications:'工作空间通知',training:'DGX 接入清单'})[dialog]}}</h2><button aria-label="关闭弹窗" @click="dialog=''"><X :size="21"/></button></div>
  <template v-if="dialog==='upload'"><p>演示版仅保存本次会话的文件信息，文件不会上传到服务器。</p><button class="upload-zone" @click="fileInput.click()"><Upload :size="30"/><strong>选择本地资料</strong><span>PDF、DOCX、TXT · 单个文件不超过 20 MB</span></button><input ref="fileInput" type="file" multiple accept=".pdf,.docx,.txt" hidden @change="handleFiles"/><ul v-if="uploadFiles.length" class="file-selection"><li v-for="f in uploadFiles" :key="f.name"><FileText :size="16"/>{{f.name}}</li></ul><label>资料领域<select v-model="uploadDomain"><option>种植管理</option><option>农业物联网</option><option>农业销售</option></select></label><p v-if="uploadError" class="error-text" role="alert">{{uploadError}}</p><div class="modal-footer"><button class="outline" @click="dialog=''">取消</button><button class="primary" @click="registerFiles">登记文件信息</button></div></template>
  <template v-else-if="dialog==='help'"><p>这是农业 AI 平台的首版 Web 交互原型，所有状态仅保留在当前页面会话，刷新即重置。</p><ul class="readable-list"><li>可操作：问答演示、评审与复审、文件信息登记、示例数据集导出、模型配置草稿。</li><li>未连接：真实大模型、Hermes、数据库、文件上传、知识检索及 DGX 训练服务。</li><li>当前身份是演示身份，尚未实现登录与多用户权限。</li><li>正式部署前将接入业务后端；模型密钥不进入前端。</li></ul></template>
  <template v-else-if="dialog==='workspace'"><div class="workspace-large"><span class="brand-mark"><Sprout :size="28"/></span><div><h3>农业 AI 工作空间</h3><p>208 亩示范园区 · 首期 AI 数据闭环</p></div></div><p>当前为演示管理员身份。园区采集、设备控制与机器人平台尚未连接。后续通过受控接口接入，数据按租户和园区隔离。</p></template>
  <template v-else-if="dialog==='notifications'"><div class="notification-entry" v-for="e in events.slice(0,5)"><Activity :size="18"/><div><strong>{{e.title}}</strong><p>{{e.detail}}</p></div></div></template>
  <template v-else-if="dialog==='training'"><p>当前仅提供前端页面，不会执行真实训练或修改设备。</p><ol class="readable-list"><li>在 DGX OS 上部署 ARM64 兼容的业务后端与数据库。</li><li>验证本地千问推理、上下文长度和工具调用。</li><li>确认同源、适合微调的权重及训练框架。</li><li>导入审核过的真实农业数据，保留独立测试集。</li><li>训练与推理错峰运行，完成评测后再发布版本。</li></ol></template>
 </section></div>
</div>
</template>
